(function(){
  'use strict';
  const flags=window.GLOBEVOY_EXPERIMENT_FLAGS||{};
  const enabled=flags.multicityExplorerVisible===true&&flags.multicityExplorerKillSwitch!==true;
  if(!enabled)return;
  const header=document.getElementById('top-bar');
  const results=document.getElementById('results-section');
  const searchCard=document.getElementById('search-card');
  if(!header||!results)return;
  if(!document.querySelector('link[href*="multicity-explorer/styles.css"]')){const css=document.createElement('link');css.rel='stylesheet';css.href='multicity-explorer/styles.css?v=11.11.3';document.head.appendChild(css);}
  const assets=['multicity-explorer/source-status-browser.js','multicity-explorer/flexible-date-windows.js','multicity-preview/link-builders.js','multicity-preview/engine.js','multicity-preview/demo-data.js','multicity-explorer/optimizer.js','multicity-explorer/city-intelligence-500.js','multicity-explorer/automatic-recommender.js','multicity-explorer/app.js'];
  const globals={'multicity-explorer/source-status-browser.js':'GlobevoyMulticitySourceStatus','multicity-explorer/flexible-date-windows.js':'GlobevoyFlexibleDateWindows','multicity-preview/link-builders.js':'GlobevoyMehdiLinks','multicity-preview/engine.js':'GlobevoyMehdiEngine','multicity-preview/demo-data.js':'GLOBEVOY_MEHDI_DEMO_DATA','multicity-explorer/optimizer.js':'GlobevoyFlexibleDurationOptimizer','multicity-explorer/city-intelligence-500.js':'GLOBEVOY_CITY_INTELLIGENCE_500','multicity-explorer/automatic-recommender.js':'GlobevoyAutomaticCityRecommender','multicity-explorer/app.js':'GlobevoyMulticityExplorerApp'};
  let loadPromise;
  function loadAssets(){if(loadPromise)return loadPromise;loadPromise=assets.reduce((p,src)=>p.then(()=>new Promise((resolve,reject)=>{if(window[globals[src]])return resolve();const s=document.createElement('script');s.src=src+'?v=11.11.3';s.onload=resolve;s.onerror=()=>reject(new Error('Could not load '+src));document.head.appendChild(s);})),Promise.resolve());return loadPromise;}
  function modeFromUrl(){const u=new URL(location.href);return u.searchParams.get('mode')==='multicity'||u.searchParams.get('tripMode')==='multi-city'?'multi':'single';}
  function initialInput(){const u=new URL(location.href),rawOrigin=(u.searchParams.get('origin')||'').trim(),originAliases={toronto:'YYZ',yyz:'YYZ','new york':'NYC',nyc:'NYC'};return {originCode:originAliases[rawOrigin.toLowerCase()]||rawOrigin||undefined,totalBudget:u.searchParams.get('budget')||undefined,currency:u.searchParams.get('currency')||undefined,dateMode:u.searchParams.get('dateMode')||'anytime',preferredMonth:u.searchParams.get('month')||undefined,totalNights:u.searchParams.get('duration')||undefined,minimumNights:u.searchParams.get('minNights')||undefined,maximumNights:u.searchParams.get('maxNights')||undefined,exactDepartureDate:u.searchParams.get('departure')||undefined,exactReturnDate:u.searchParams.get('return')||undefined,preferences:(u.searchParams.get('preferences')||'').split(',').filter(Boolean)};}
  function updateHistory(mode,replace){const u=new URL(location.href);u.searchParams.delete('tripMode');if(mode==='multi')u.searchParams.set('mode','multicity');else u.searchParams.delete('mode');history[replace?'replaceState':'pushState']({globevoyTripMode:mode},'',u);}
  const bar=document.createElement('section');bar.className='gv-trip-mode-bar';bar.innerHTML='<div class="gv-trip-mode-panel"><nav class="gv-trip-mode-switch" aria-label="Trip type" role="tablist"><button type="button" class="active" role="tab" aria-selected="true">Single destination</button><button type="button" role="tab" aria-selected="false">Multi-city</button></nav></div>';
  const toolbar=document.createElement('section');toolbar.className='gv-result-toolbar';toolbar.setAttribute('aria-label','Single-destination result controls');toolbar.innerHTML='<div class="gv-single-tools"><button class="ss-edit" id="ss-edit-btn" type="button" aria-controls="search-card" aria-expanded="false">Edit search</button><button class="ss-shuffle" id="sc-surprise" type="button">Shuffle</button><div class="view-toggle" role="group" aria-label="Switch between Explorer and List"><button class="view-tab active" id="explorer-view-btn" type="button" aria-pressed="true">Explorer</button><button class="view-tab" id="list-view-btn" type="button" aria-pressed="false">List</button></div></div>';
  const [singleBtn,multiBtn]=bar.querySelectorAll('button');
  const root=document.createElement('section');root.id='multicity-explorer-root';root.hidden=true;root.setAttribute('aria-label','Multi-city recommendations');
  header.insertAdjacentElement('afterend',bar);bar.insertAdjacentElement('afterend',toolbar);if(searchCard){toolbar.insertAdjacentElement('afterend',searchCard);searchCard.insertAdjacentElement('afterend',root);}else toolbar.insertAdjacentElement('afterend',root);
  const state={mode:'single'};
  const singleTools=toolbar.querySelector('.gv-single-tools');
  function multicityContext(){const u=new URL(location.href),currency=(u.searchParams.get('currency')||'CAD').toUpperCase(),amount=Number(u.searchParams.get('budget')||5000),origin=u.searchParams.get('origin')||'YYZ',names={YYZ:'Toronto',NYC:'New York'},symbols={CAD:'C$',USD:'$',AUD:'A$',EUR:'€',GBP:'£'};const value=(symbols[currency]||'')+amount.toLocaleString('en-CA',{maximumFractionDigits:0});return (names[origin]||origin)+' · '+value+' '+currency;}
  function setSelected(mode){const multi=mode==='multi';document.body.classList.toggle('gv-multicity-mode',multi);singleBtn.classList.toggle('active',!multi);multiBtn.classList.toggle('active',multi);singleBtn.setAttribute('aria-selected',multi?'false':'true');multiBtn.setAttribute('aria-selected',multi?'true':'false');toolbar.hidden=multi;singleTools.hidden=multi;results.hidden=multi;if(multi)window.dispatchEvent(new CustomEvent('globevoy:close-single-search'));root.hidden=!multi;const context=document.getElementById('ss-text');if(multi&&context)context.textContent=multicityContext()+' · Multi-city';if(!multi)window.dispatchEvent(new CustomEvent('globevoy:single-mode'));}
  async function setMode(mode,opts={}){if(mode===state.mode&&!opts.force){setSelected(mode);return;}if(mode==='multi'){const old=multiBtn.textContent;multiBtn.disabled=true;multiBtn.textContent='Loading...';try{await loadAssets();setSelected('multi');if(!root.dataset.mounted){window.GlobevoyMulticityExplorerApp.mount(root,{initialInput:initialInput(),flags});root.dataset.mounted='true';}state.mode='multi';if(!opts.popstate)updateHistory('multi',opts.replace);}catch(e){root.hidden=false;root.innerHTML='<section class="gv-mc-empty"><h3>Multi-city could not load</h3><p>'+e.message+'</p></section>';}finally{multiBtn.disabled=false;multiBtn.textContent=old;}}else{setSelected('single');state.mode='single';if(!opts.popstate)updateHistory('single',opts.replace);}}
  singleBtn.addEventListener('click',()=>setMode('single'));multiBtn.addEventListener('click',()=>setMode('multi'));
  toolbar.querySelector('#ss-edit-btn').addEventListener('click',()=>{if(searchCard)window.dispatchEvent(new CustomEvent('globevoy:toggle-single-search'));else{const u=new URL('index.html',location.href);const current=new URL(location.href);['origin','budget','currency'].forEach(key=>{const value=current.searchParams.get(key);if(value)u.searchParams.set(key,value);});location.href=u.href;}});
  toolbar.querySelector('#sc-surprise').addEventListener('click',()=>window.dispatchEvent(new CustomEvent('globevoy:shuffle-single')));
  toolbar.querySelector('#explorer-view-btn').addEventListener('click',()=>window.dispatchEvent(new CustomEvent('globevoy:set-single-view',{detail:{view:'explorer'}})));
  toolbar.querySelector('#list-view-btn').addEventListener('click',()=>window.dispatchEvent(new CustomEvent('globevoy:set-single-view',{detail:{view:'list'}})));
  window.addEventListener('globevoy:multicity-results',event=>{const count=Number(event.detail&&event.detail.count)||0;const context=document.getElementById('ss-text');if(context&&event.detail)context.textContent=event.detail.context+' · '+count+' recommended trip'+(count===1?'':'s');});
  window.addEventListener('popstate',()=>setMode(modeFromUrl(),{popstate:true,force:true}));
  if(modeFromUrl()==='multi')setMode('multi',{replace:true,force:true});else setSelected('single');
})();
